// Foreground, opt-in location reminder; food-app events remain an explicit demo.
(()=>{
const coreRender=render,coreGo=go;let watch=null,place=null,insideSince=null,alreadySent=false,lastFix=null,monitorTicker=null,demoTimer=null;
const reminderText='Thinking of eating soon? Check your personal meal and insulin plan, including timing.';
function icon(){try{const c=document.createElement('canvas');c.width=480;c.height=310;paintWorld(c,state.equipped.Rooms||'cozy',state.equipped,'range','Reading',true,false,Date.now());return c.toDataURL('image/png')}catch{return ''}}
function notify(source){const title=state.characterName+' has a gentle reminder';const overlay=document.createElement('section');overlay.className='reminder-popup';overlay.setAttribute('role','status');overlay.innerHTML=`<canvas width="480" height="310" aria-label="Your customized companion"></canvas><div><small>${escapeHTML(source)}</small><strong>${escapeHTML(title)}</strong><p>${escapeHTML(reminderText)}</p><button type="button">Got it</button></div>`;document.body.appendChild(overlay);try{paintWorld(overlay.querySelector('canvas'),state.equipped.Rooms||'cozy',state.equipped,'range','Reading',true,false,Date.now())}catch{}overlay.querySelector('button').onclick=()=>overlay.remove();setTimeout(()=>overlay.remove(),18000);if(window.Notification&&Notification.permission==='granted'){try{new Notification(title,{body:reminderText,icon:icon(),tag:'diabuddy-meal-reminder'})}catch{}}}
function distance(a,b){const rad=x=>x*Math.PI/180;const dLat=rad(a.lat-b.lat),dLon=rad(a.lon-b.lon),h=Math.sin(dLat/2)**2+Math.cos(rad(a.lat))*Math.cos(rad(b.lat))*Math.sin(dLon/2)**2;return 6371000*2*Math.atan2(Math.sqrt(h),Math.sqrt(1-h))}
function resetDwell(){insideSince=null;alreadySent=false;lastFix=null}
function stop(){if(watch!==null)navigator.geolocation.clearWatch(watch);watch=null;clearInterval(monitorTicker);resetDwell()}
function status(t){const el=$('#reminder-status');if(el)el.textContent=t}
function tick(){if(!place||insideSince===null||!lastFix||Date.now()-lastFix>30000||document.hidden)return;const elapsed=Date.now()-insideSince;status(`At your chosen place · ${Math.min(place.minutes,Math.floor(elapsed/60000))}/${place.minutes} min. Keep this app open.`);if(elapsed>=place.minutes*60000&&!alreadySent){alreadySent=true;notify('YOUR SAVED PLACE · FOREGROUND ONLY');status('Reminder shown. Leave and return for another reminder.')}}
function monitor(){if(!navigator.geolocation){status('Location is unavailable in this browser.');return}stop();watch=navigator.geolocation.watchPosition(pos=>{if(!place||document.hidden)return;const p={lat:pos.coords.latitude,lon:pos.coords.longitude};if(!Number.isFinite(pos.coords.accuracy)||pos.coords.accuracy>100){resetDwell();status('Location is too uncertain. Move to an area with a clearer signal.');return}if(lastFix!==null&&Date.now()-lastFix>30000)insideSince=null;lastFix=Date.now();if(distance(p,place)<=100){if(insideSince===null)insideSince=Date.now();tick()}else{resetDwell();status('Outside your chosen area. Waiting for a return visit.')}},err=>{status('Location unavailable: '+err.message);stop();place=null},{enableHighAccuracy:true,maximumAge:10000,timeout:20000});monitorTicker=setInterval(tick,1000)}
function reminderPage(){content.innerHTML=greeting('A little reminder, from a friend.','Your companion can help you remember to check your personal plan.','MEAL REMINDERS')+`<section class="card card-pad"><h2>Try the demo</h2><p>Show a character notification without visiting a restaurant or opening another app.</p><div class="reminder-actions"><button class="primary" id="demo-place">Simulate a visit · 5 seconds</button><button class="secondary" id="demo-food-app">Simulate opening a food app</button><button class="secondary" id="demo-cancel">Cancel demo</button></div><p class="helper" id="demo-status" role="status">Demo events are simulated and don’t monitor your device.</p></section><section class="card card-pad" style="margin-top:18px"><h2>Try a chosen place</h2><p>With your permission, use your current location as a test place. When you’re within approximately 100 m for the chosen time, your companion sends a reminder while this app stays open and visible.</p><label for="dwell-minutes">Time at place</label><select id="dwell-minutes"><option value="1">1 minute</option><option value="2">2 minutes</option></select><div class="reminder-actions"><button class="secondary" id="enable-notifications">Allow system notifications</button><button class="primary" id="set-place">Use my current location & start</button><button class="secondary" id="stop-place">Stop & forget place</button></div><p class="helper" id="reminder-status" role="status">${place?'Monitoring your chosen place while visible.':'Not monitoring. No place has been selected.'}</p><p class="helper">Your selected coordinates are held only while this page is open; they are not sent to a location service by this app. GPS may not identify a building and can be inaccurate indoors. Closing or hiding the app stops this foreground monitor. The web app cannot see when another app opens.</p><p class="notice">Reminders are optional and do not determine whether to bolus or when to eat. Follow your personal care plan. Never delay treatment for low glucose.</p></section>`;
$('#demo-place').onclick=()=>{clearTimeout(demoTimer);$('#demo-status').textContent='SIMULATED: At a food establishment. Reminder in 5 seconds (represents 1–2 minutes).';demoTimer=setTimeout(()=>{notify('SIMULATED · RESTAURANT VISIT');const e=$('#demo-status');if(e)e.textContent='Simulated visit complete.'},5000)};$('#demo-food-app').onclick=()=>notify('SIMULATED · FOOD APP OPENED');$('#demo-cancel').onclick=()=>{clearTimeout(demoTimer);$('#demo-status').textContent='Demo cancelled.'};$('#enable-notifications').onclick=async()=>{if(!window.Notification){status('System notifications are not available in this browser. In-app reminders still work.');return}try{const permission=await Notification.requestPermission();status(permission==='granted'?'System notification permission granted.':'System notifications are not enabled. In-app reminders still work.')}catch{status('System notifications unavailable here. In-app reminders still work.')}};$('#set-place').onclick=()=>{if(!navigator.geolocation){status('Location is unavailable in this browser.');return}const mins=Number($('#dwell-minutes').value);status('Requesting location permission…');navigator.geolocation.getCurrentPosition(pos=>{if(document.hidden){status('Keep the app visible while selecting a place.');return}if(!Number.isFinite(pos.coords.accuracy)||pos.coords.accuracy>100){status('Location is too uncertain to save this place. Please try again with a stronger signal.');return}place={lat:pos.coords.latitude,lon:pos.coords.longitude,minutes:mins};monitor();status('Place selected. Keep this app visible while testing.')},err=>status('Location unavailable: '+err.message),{enableHighAccuracy:true,maximumAge:0,timeout:20000})};$('#stop-place').onclick=()=>{stop();place=null;status('Monitoring stopped and the selected place was forgotten.')};}
render=function(){coreRender();if(page==='reminders')reminderPage()};go=function(p){coreGo(p);if(p==='reminders')$('#page-label').textContent='MEAL REMINDERS'};
document.addEventListener('visibilitychange',()=>{if(document.hidden&&place){stop();place=null;status('Monitoring stopped when the app was hidden. Select a place again to restart.')}});
})();
